-- 세트 510. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set510.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 510, 'SQL 중급 (2) JOIN 확장과 UNION: RIGHT·CROSS·SELF JOIN, UNION 과 UNION ALL', 'INNER·LEFT JOIN 다음 단계입니다. RIGHT JOIN, CROSS JOIN(모든 조합), SELF JOIN(같은 테이블끼리 이어 직원-상사 찾기), UNION 과 UNION ALL(중복 제거 여부, 정렬 규칙)을 개념 문제와 터미널 실습으로 익힙니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 510);
UPDATE quest_set SET display_order = 731, unit_id = (SELECT id FROM unit WHERE id = 44), icon = '🔗' WHERE id = 510;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 1, 'RIGHT JOIN 은 LEFT JOIN 의 거울', '`FROM emp e RIGHT JOIN dept d ON e.dept_id = d.id` 에서 **조건이 맞지 않아도 모두 남는 쪽**은 어느 테이블일까요?', '`LEFT JOIN` 은 `JOIN` 왼쪽 테이블을 모두 남깁니다. `RIGHT` 는 그 반대 쪽입니다.', NULL, NULL, '[]', 'choice', '["왼쪽 테이블 `emp` 의 모든 행", "오른쪽 테이블 `dept` 의 모든 행", "양쪽 테이블의 모든 행", "조건에 맞는 행만 남는다"]', 1, '`RIGHT JOIN` 은 오른쪽(`JOIN` 뒤에 쓴 테이블) 행을 모두 남기고, 왼쪽에 짝이 없으면 왼쪽 칸을 `NULL` 로 채웁니다. 두 테이블 순서를 바꾼 `LEFT JOIN` 과 같은 결과라 실무에서는 대부분 `LEFT JOIN` 으로 통일해 씁니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 2, '직원이 없는 부서 찾기 (RIGHT JOIN)', '`hr` 데이터베이스에는 `dept`(부서)와 `emp`(직원: `dept_id` 가 부서 번호) 테이블이 있습니다. **`emp` 를 왼쪽, `dept` 를 오른쪽**에 두고 `RIGHT JOIN` 해서, **직원이 한 명도 없는 부서의 이름**을 `/tmp/empty.txt` 에 저장하세요. (제목 줄 없이 이름만)', '`emp` 를 왼쪽, `dept` 를 오른쪽에 두고 `RIGHT JOIN` 하면 짝 없는 부서의 직원 칸은 `NULL` 이 됩니다. 그 행만 `WHERE` 로 거르세요. `mariadb -N hr -e "..."` 의 출력을 `>` 로 저장합니다.', 'mariadb -N hr -e ''SELECT d.name FROM emp e RIGHT JOIN dept d ON e.dept_id = d.id WHERE e.id IS NULL'' > /tmp/empty.txt
cat /tmp/empty.txt

# 오른쪽(dept)은 모두 남고, 직원이 없는 부서는 e 칸이 NULL. 그 행만 고르면 직원 없는 부서', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS hr; CREATE DATABASE hr; USE hr; CREATE TABLE dept (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE emp (id INT PRIMARY KEY, name VARCHAR(20), dept_id INT, manager_id INT); INSERT INTO dept VALUES (1,\\"dev\\"),(2,\\"sales\\"),(3,\\"hr\\"); INSERT INTO emp VALUES (1,\\"park\\",1,NULL),(2,\\"kim\\",1,1),(3,\\"lee\\",2,1),(4,\\"choi\\",NULL,2),(5,\\"han\\",2,3); CREATE TABLE sizes (label VARCHAR(5)); INSERT INTO sizes VALUES (\\"S\\"),(\\"M\\"),(\\"L\\"); CREATE TABLE colors (name VARCHAR(10)); INSERT INTO colors VALUES (\\"red\\"),(\\"blue\\"); CREATE TABLE list_a (email VARCHAR(30)); CREATE TABLE list_b (email VARCHAR(30)); INSERT INTO list_a VALUES (\\"x@example.com\\"),(\\"y@example.com\\"),(\\"z@example.com\\"); INSERT INTO list_b VALUES (\\"y@example.com\\"),(\\"z@example.com\\"),(\\"w@example.com\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/empty.txt ] ) && ( [ \\"$(cat /tmp/empty.txt)\\" = hr ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/empty.txt ]"]}, {"label": "직원 없는 부서 hr 하나만 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/empty.txt)\\" = hr ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB UNION", "url": "https://mariadb.com/kb/en/union/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 3, '모든 조합 만들기 (CROSS JOIN)', '`hr` 데이터베이스에서 쇼핑몰의 **크기(`sizes`: S, M, L)** 와 **색상(`colors`: red, blue)** 의 가능한 **모든 조합**을 만들려 합니다. `CROSS JOIN` 은 `ON` 없이 한쪽의 모든 행을 다른 쪽의 모든 행과 짝짓습니다. `sizes` 의 `label` 과 `colors` 의 `name` 두 열을 조합해 `/tmp/combo.txt` 에 저장하세요. (제목 줄 없이)', '`FROM sizes CROSS JOIN colors` 로 잇습니다. `ON` 은 쓰지 않습니다. 결과 행 수는 3 × 2 입니다.', 'mariadb -N hr -e ''SELECT s.label, c.name FROM sizes s CROSS JOIN colors c'' > /tmp/combo.txt
cat /tmp/combo.txt

# 행 수는 3 x 2 = 6. 조건 없는 JOIN 은 곱한 만큼 행이 나온다. 의도한 경우(조합 만들기)에만 쓴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS hr; CREATE DATABASE hr; USE hr; CREATE TABLE dept (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE emp (id INT PRIMARY KEY, name VARCHAR(20), dept_id INT, manager_id INT); INSERT INTO dept VALUES (1,\\"dev\\"),(2,\\"sales\\"),(3,\\"hr\\"); INSERT INTO emp VALUES (1,\\"park\\",1,NULL),(2,\\"kim\\",1,1),(3,\\"lee\\",2,1),(4,\\"choi\\",NULL,2),(5,\\"han\\",2,3); CREATE TABLE sizes (label VARCHAR(5)); INSERT INTO sizes VALUES (\\"S\\"),(\\"M\\"),(\\"L\\"); CREATE TABLE colors (name VARCHAR(10)); INSERT INTO colors VALUES (\\"red\\"),(\\"blue\\"); CREATE TABLE list_a (email VARCHAR(30)); CREATE TABLE list_b (email VARCHAR(30)); INSERT INTO list_a VALUES (\\"x@example.com\\"),(\\"y@example.com\\"),(\\"z@example.com\\"); INSERT INTO list_b VALUES (\\"y@example.com\\"),(\\"z@example.com\\"),(\\"w@example.com\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/combo.txt)\\" = 6 ] ) && ( grep -q \\"^L.blue$\\" /tmp/combo.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "6줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/combo.txt)\\" = 6 ]"]}, {"label": "L 과 blue 조합이 있다", "cmd": ["sh", "-c", "grep -q \\"^L.blue$\\" /tmp/combo.txt"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB UNION", "url": "https://mariadb.com/kb/en/union/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 4, 'CROSS JOIN 의 행 수', '크기 테이블이 4행, 색상 테이블이 5행입니다. `SELECT * FROM sizes CROSS JOIN colors` 는 몇 행을 돌려줄까요?', '짝짓는 방법은 "모든 행 × 모든 행" 입니다.', NULL, NULL, '[]', 'choice', '["9행", "5행", "20행", "4행"]', 2, 'CROSS JOIN 은 한쪽의 모든 행을 다른 쪽의 모든 행과 짝지어 4 × 5 = 20 행이 나옵니다. 행이 많은 두 테이블에 실수로 `ON` 을 빠뜨리면 결과가 폭발적으로 커집니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 5, '직원과 상사 이름 함께 보기 (SELF JOIN)', '`hr` 데이터베이스의 `emp` 테이블의 `manager_id` 는 **같은 테이블의 다른 직원 `id`** 를 가리킵니다(상사). 같은 테이블을 두 번 쓰려면 **서로 다른 별칭**이 필요합니다. `emp e` (직원)와 `emp m` (상사)를 `e.manager_id = m.id` 로 `JOIN` 해서 **직원 이름과 상사 이름**을 `/tmp/boss.txt` 에 저장하세요. (제목 줄 없이)', '`FROM emp e JOIN emp m ON e.manager_id = m.id` 입니다. 같은 테이블이어도 `e`, `m` 으로 나누면 서로 다른 테이블처럼 쓸 수 있습니다. `SELECT e.name, m.name` 으로 뽑으세요.', 'mariadb -N hr -e ''SELECT e.name, m.name FROM emp e JOIN emp m ON e.manager_id = m.id'' > /tmp/boss.txt
cat /tmp/boss.txt

# SELF JOIN: 같은 테이블에 별칭 두 개를 붙여 잇는다. 상사가 없는 park 은 INNER JOIN 이라 빠진다 (4줄)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS hr; CREATE DATABASE hr; USE hr; CREATE TABLE dept (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE emp (id INT PRIMARY KEY, name VARCHAR(20), dept_id INT, manager_id INT); INSERT INTO dept VALUES (1,\\"dev\\"),(2,\\"sales\\"),(3,\\"hr\\"); INSERT INTO emp VALUES (1,\\"park\\",1,NULL),(2,\\"kim\\",1,1),(3,\\"lee\\",2,1),(4,\\"choi\\",NULL,2),(5,\\"han\\",2,3); CREATE TABLE sizes (label VARCHAR(5)); INSERT INTO sizes VALUES (\\"S\\"),(\\"M\\"),(\\"L\\"); CREATE TABLE colors (name VARCHAR(10)); INSERT INTO colors VALUES (\\"red\\"),(\\"blue\\"); CREATE TABLE list_a (email VARCHAR(30)); CREATE TABLE list_b (email VARCHAR(30)); INSERT INTO list_a VALUES (\\"x@example.com\\"),(\\"y@example.com\\"),(\\"z@example.com\\"); INSERT INTO list_b VALUES (\\"y@example.com\\"),(\\"z@example.com\\"),(\\"w@example.com\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/boss.txt)\\" = 4 ] ) && ( awk -F\\"\\\\t\\" ''$1==\\"choi\\" && $2==\\"kim\\"'' /tmp/boss.txt | grep -q . )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "4줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/boss.txt)\\" = 4 ]"]}, {"label": "choi 의 상사는 kim 이다", "cmd": ["sh", "-c", "awk -F\\"\\\\t\\" ''$1==\\"choi\\" && $2==\\"kim\\"'' /tmp/boss.txt | grep -q ."]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB UNION", "url": "https://mariadb.com/kb/en/union/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 6, '상사가 없는 사람도 함께 보기', '`hr` 데이터베이스의 `emp` 로 앞 문제와 같은 조회를 합니다. 앞의 결과에는 **상사가 없는 최상위 직원(`park`)이 빠졌습니다.** `INNER JOIN` 은 짝이 없는 행을 버리기 때문입니다. `LEFT JOIN` 으로 바꿔 **모든 직원**(5명)이 나오게 하고, 직원 이름과 상사 이름을 `/tmp/boss_all.txt` 에 저장하세요. 상사가 없는 줄은 상사 칸이 `NULL` 이어야 합니다.', '앞 문제의 `JOIN` 을 `LEFT JOIN` 으로 바꾸면 왼쪽(직원 `e`)이 모두 남습니다.', 'mariadb -N hr -e ''SELECT e.name, m.name FROM emp e LEFT JOIN emp m ON e.manager_id = m.id'' > /tmp/boss_all.txt
cat /tmp/boss_all.txt

# 최상위 직원은 상사 칸이 NULL 로 나온다. 조직도처럼 모두 보여야 할 때는 SELF JOIN 도 LEFT JOIN 으로 쓴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS hr; CREATE DATABASE hr; USE hr; CREATE TABLE dept (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE emp (id INT PRIMARY KEY, name VARCHAR(20), dept_id INT, manager_id INT); INSERT INTO dept VALUES (1,\\"dev\\"),(2,\\"sales\\"),(3,\\"hr\\"); INSERT INTO emp VALUES (1,\\"park\\",1,NULL),(2,\\"kim\\",1,1),(3,\\"lee\\",2,1),(4,\\"choi\\",NULL,2),(5,\\"han\\",2,3); CREATE TABLE sizes (label VARCHAR(5)); INSERT INTO sizes VALUES (\\"S\\"),(\\"M\\"),(\\"L\\"); CREATE TABLE colors (name VARCHAR(10)); INSERT INTO colors VALUES (\\"red\\"),(\\"blue\\"); CREATE TABLE list_a (email VARCHAR(30)); CREATE TABLE list_b (email VARCHAR(30)); INSERT INTO list_a VALUES (\\"x@example.com\\"),(\\"y@example.com\\"),(\\"z@example.com\\"); INSERT INTO list_b VALUES (\\"y@example.com\\"),(\\"z@example.com\\"),(\\"w@example.com\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/boss_all.txt)\\" = 5 ] ) && ( awk -F\\"\\\\t\\" ''$1==\\"park\\" && $2==\\"NULL\\"'' /tmp/boss_all.txt | grep -q . )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "5줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/boss_all.txt)\\" = 5 ]"]}, {"label": "park 의 상사 칸이 NULL 이다", "cmd": ["sh", "-c", "awk -F\\"\\\\t\\" ''$1==\\"park\\" && $2==\\"NULL\\"'' /tmp/boss_all.txt | grep -q ."]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB UNION", "url": "https://mariadb.com/kb/en/union/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 7, '직원-상사 조회 쿼리 조립', '상사가 없는 직원까지 포함해 **직원 이름과 상사 이름을 직원 이름순**으로 보는 쿼리입니다. SQL 에서 쓰는 순서대로 놓으세요.', '무엇을 고를지, 어디서 가져올지, 어떻게 이을지, 마지막에 정렬하는 순서입니다.', NULL, NULL, '[]', 'order', '["ON e.manager_id = m.id", "SELECT e.name, m.name", "ORDER BY e.name", "FROM emp e", "LEFT JOIN emp m"]', NULL, '`SELECT` 로 열을 고르고 `FROM` 으로 기준 테이블(별칭 e)을 정한 뒤 `LEFT JOIN` 으로 같은 테이블을 다른 별칭(m)으로 이어 `ON` 에 조건을 적습니다. `ORDER BY` 는 맨 마지막입니다.', '[1, 3, 4, 0, 2]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 8, '두 목록 합치기 (UNION)', '`hr` 데이터베이스의 `list_a` 와 `list_b` 는 서로 다른 행사의 이메일 목록이고 **겹치는 주소가 있습니다.** `UNION` 은 두 `SELECT` 결과를 **위아래로 이어 붙이고 중복을 제거**합니다. 두 목록의 `email` 을 `UNION` 해서 `/tmp/union.txt` 에 저장하세요. (제목 줄 없이. 중복 없는 주소 4개)', '`SELECT email FROM list_a UNION SELECT email FROM list_b` 입니다. 두 `SELECT` 의 열 개수와 순서가 같아야 합니다.', 'mariadb -N hr -e ''SELECT email FROM list_a UNION SELECT email FROM list_b'' > /tmp/union.txt
cat /tmp/union.txt

# UNION 은 위아래로 이어 붙이고 중복 행을 없앤다. 열 개수가 같아야 하고, JOIN(옆으로 이음)과 다르다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS hr; CREATE DATABASE hr; USE hr; CREATE TABLE dept (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE emp (id INT PRIMARY KEY, name VARCHAR(20), dept_id INT, manager_id INT); INSERT INTO dept VALUES (1,\\"dev\\"),(2,\\"sales\\"),(3,\\"hr\\"); INSERT INTO emp VALUES (1,\\"park\\",1,NULL),(2,\\"kim\\",1,1),(3,\\"lee\\",2,1),(4,\\"choi\\",NULL,2),(5,\\"han\\",2,3); CREATE TABLE sizes (label VARCHAR(5)); INSERT INTO sizes VALUES (\\"S\\"),(\\"M\\"),(\\"L\\"); CREATE TABLE colors (name VARCHAR(10)); INSERT INTO colors VALUES (\\"red\\"),(\\"blue\\"); CREATE TABLE list_a (email VARCHAR(30)); CREATE TABLE list_b (email VARCHAR(30)); INSERT INTO list_a VALUES (\\"x@example.com\\"),(\\"y@example.com\\"),(\\"z@example.com\\"); INSERT INTO list_b VALUES (\\"y@example.com\\"),(\\"z@example.com\\"),(\\"w@example.com\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/union.txt)\\" = 4 ] ) && ( [ \\"$(sort /tmp/union.txt | uniq | grep -c .)\\" = 4 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "4줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/union.txt)\\" = 4 ]"]}, {"label": "중복이 없다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/union.txt | uniq | grep -c .)\\" = 4 ]"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB UNION", "url": "https://mariadb.com/kb/en/union/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 9, '중복을 남기고 정렬해서 합치기 (UNION ALL)', '`hr` 데이터베이스의 `list_a`, `list_b` 를 씁니다. 이번에는 **중복을 지우지 않고** 모든 행(6개)을 이어 붙입니다. `UNION ALL` 은 중복 제거를 하지 않아 더 빠릅니다. 두 목록을 `UNION ALL` 하고, **전체 결과를 `email` 순으로 정렬**해 `/tmp/all.txt` 에 저장하세요. `ORDER BY` 는 **마지막 `SELECT` 뒤에 한 번만** 쓰면 합친 전체 결과에 적용됩니다.', '`SELECT email FROM list_a UNION ALL SELECT email FROM list_b ORDER BY email` 입니다. 두 번째 `SELECT` 끝에만 `ORDER BY` 를 붙입니다.', 'mariadb -N hr -e ''SELECT email FROM list_a UNION ALL SELECT email FROM list_b ORDER BY email'' > /tmp/all.txt
cat /tmp/all.txt

# UNION ALL 은 중복을 그대로 둔다 (6줄). 마지막 ORDER BY 는 합친 전체 결과를 정렬한다. 중복이 없다고 확실하면 UNION ALL 이 더 빠르다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS hr; CREATE DATABASE hr; USE hr; CREATE TABLE dept (id INT PRIMARY KEY, name VARCHAR(20)); CREATE TABLE emp (id INT PRIMARY KEY, name VARCHAR(20), dept_id INT, manager_id INT); INSERT INTO dept VALUES (1,\\"dev\\"),(2,\\"sales\\"),(3,\\"hr\\"); INSERT INTO emp VALUES (1,\\"park\\",1,NULL),(2,\\"kim\\",1,1),(3,\\"lee\\",2,1),(4,\\"choi\\",NULL,2),(5,\\"han\\",2,3); CREATE TABLE sizes (label VARCHAR(5)); INSERT INTO sizes VALUES (\\"S\\"),(\\"M\\"),(\\"L\\"); CREATE TABLE colors (name VARCHAR(10)); INSERT INTO colors VALUES (\\"red\\"),(\\"blue\\"); CREATE TABLE list_a (email VARCHAR(30)); CREATE TABLE list_b (email VARCHAR(30)); INSERT INTO list_a VALUES (\\"x@example.com\\"),(\\"y@example.com\\"),(\\"z@example.com\\"); INSERT INTO list_b VALUES (\\"y@example.com\\"),(\\"z@example.com\\"),(\\"w@example.com\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/all.txt)\\" = 6 ] ) && ( LC_ALL=C sort -c /tmp/all.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "6줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/all.txt)\\" = 6 ]"]}, {"label": "이메일 순으로 정렬돼 있다", "cmd": ["sh", "-c", "LC_ALL=C sort -c /tmp/all.txt"]}]', '[{"title": "MariaDB JOIN 문법", "url": "https://mariadb.com/kb/en/join-syntax/"}, {"title": "MariaDB UNION", "url": "https://mariadb.com/kb/en/union/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 10, '중복을 남기는 합치기', '두 `SELECT` 결과를 **중복을 지우지 않고** 이어 붙이는 문장입니다. 빈칸을 채우세요.', '`UNION` 뒤에 붙여 중복 제거를 건너뛰게 하는 키워드입니다.', NULL, NULL, '[]', 'fill', '["ALL", "FULL", "EACH", "KEEP"]', NULL, '`UNION ALL` 은 중복을 제거하지 않고 모든 행을 그대로 이어 붙입니다. 그냥 `UNION` 은 중복을 제거합니다. 나머지는 UNION 뒤에 올 수 있는 키워드가 아닙니다.', '[0]', 'SELECT email FROM list_a UNION {0} SELECT email FROM list_b;', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 510, 11, 'FULL OUTER JOIN 이 필요할 때', '양쪽 테이블의 짝 없는 행까지 **모두** 남기고 싶습니다(FULL OUTER JOIN). MariaDB 에는 `FULL JOIN` 문법이 없습니다. 어떻게 같은 결과를 만들까요?', '앞에서 배운 LEFT JOIN, RIGHT JOIN, UNION 을 조합해 보세요.', NULL, NULL, '[]', 'choice', '["`CROSS JOIN` 을 쓴다", "`INNER JOIN` 에 `WHERE` 를 더한다", "`UNION ALL` 만 쓰면 된다", "`LEFT JOIN` 결과와 `RIGHT JOIN` 결과를 `UNION` 으로 합친다"]', 3, '`LEFT JOIN` 은 왼쪽을, `RIGHT JOIN` 은 오른쪽을 모두 남깁니다. 둘을 `UNION` 으로 합치면 양쪽이 모두 남고, 짝이 있는 행의 중복은 `UNION` 이 제거합니다. `UNION ALL` 이면 짝이 있는 행이 두 번 나옵니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 510 AND order_index = 11);
